"use client";

import { useEffect, useRef, useState } from "react";

interface Particle {
  id: number;
  x: number;
  y: number;
  size: number;
  born: number;
}

interface Ripple {
  id: number;
  x: number;
  y: number;
  born: number;
}

const PARTICLE_LIFE = 700; // ms
const PARTICLE_INTERVAL = 45; // ms between particles
const MAX_PARTICLES = 25;
const RIPPLE_LIFE = 800; // ms

/**
 * CursorGlow — a layered, interactive cursor effect:
 *  - Outer soft glow that lerps toward the mouse (lagging)
 *  - Inner crisp dot that follows tightly with velocity-based scaling
 *  - Trailing particles emitted on movement (decay over ~700ms)
 *  - Click ripples expanding from click position
 * Disabled on touch devices and reduced-motion users.
 */
export default function CursorGlow() {
  const [enabled, setEnabled] = useState(false);
  const dotRef = useRef<HTMLDivElement | null>(null);
  const glowRef = useRef<HTMLDivElement | null>(null);
  const particleLayerRef = useRef<HTMLDivElement | null>(null);

  // Position refs (no re-render needed for movement)
  const mouse = useRef({ x: -100, y: -100 });
  const glow = useRef({ x: -100, y: -100 });
  const lastParticleAt = useRef(0);
  const particleId = useRef(0);
  const rippleId = useRef(0);

  // Visible state for hover effects on interactive elements
  const [hovering, setHovering] = useState(false);

  useEffect(() => {
    const isTouch =
      typeof window !== "undefined" &&
      (window.matchMedia?.("(hover: none)")?.matches ||
        "ontouchstart" in window);
    const reduce = window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches;
    if (!isTouch && !reduce) setEnabled(true);
  }, []);

  useEffect(() => {
    if (!enabled) return;

    const onMove = (e: MouseEvent) => {
      mouse.current.x = e.clientX;
      mouse.current.y = e.clientY;
      // Hover state for interactive elements
      const el = e.target as HTMLElement;
      if (
        el.closest("a, button, [role='button'], input, textarea, select, label")
      ) {
        setHovering(true);
      } else {
        setHovering(false);
      }
    };

    const onDown = (e: MouseEvent) => {
      const layer = particleLayerRef.current;
      if (!layer) return;
      const id = rippleId.current++;
      const r: Ripple = { id, x: e.clientX, y: e.clientY, born: performance.now() };
      const node = document.createElement("div");
      node.dataset.ripple = "1";
      node.style.position = "absolute";
      node.style.left = `${r.x}px`;
      node.style.top = `${r.y}px`;
      node.style.transform = "translate(-50%, -50%)";
      node.style.width = "10px";
      node.style.height = "10px";
      node.style.borderRadius = "9999px";
      node.style.border = "1.5px solid #C71F42";
      node.style.pointerEvents = "none";
      node.style.opacity = "0.9";
      node.style.transition = `transform ${RIPPLE_LIFE}ms cubic-bezier(0.22,1,0.36,1), opacity ${RIPPLE_LIFE}ms ease-out`;
      layer.appendChild(node);
      // Trigger animation on next frame
      requestAnimationFrame(() => {
        node.style.transform = "translate(-50%, -50%) scale(20)";
        node.style.opacity = "0";
      });
      setTimeout(() => node.remove(), RIPPLE_LIFE + 50);
    };

    window.addEventListener("mousemove", onMove, { passive: true });
    window.addEventListener("mousedown", onDown, { passive: true });

    let raf = 0;
    let prevX = mouse.current.x;
    let prevY = mouse.current.y;
    let prevT = performance.now();

    const tick = () => {
      const now = performance.now();
      // Smooth glow trail (lerp)
      glow.current.x += (mouse.current.x - glow.current.x) * 0.18;
      glow.current.y += (mouse.current.y - glow.current.y) * 0.18;

      const dt = now - prevT;
      const dx = mouse.current.x - prevX;
      const dy = mouse.current.y - prevY;
      const velocity = Math.hypot(dx, dy) / Math.max(1, dt);
      prevX = mouse.current.x;
      prevY = mouse.current.y;
      prevT = now;

      if (dotRef.current) {
        dotRef.current.style.transform = `translate3d(${mouse.current.x}px, ${mouse.current.y}px, 0) translate(-50%, -50%) scale(${1 + Math.min(velocity * 0.18, 0.6)})`;
        dotRef.current.style.opacity = "1";
      }
      if (glowRef.current) {
        const scale = hovering ? 2.2 : 1.4 + Math.min(velocity * 0.12, 0.8);
        glowRef.current.style.transform = `translate3d(${glow.current.x}px, ${glow.current.y}px, 0) translate(-50%, -50%) scale(${scale})`;
        glowRef.current.style.opacity = hovering ? "0.85" : "0.55";
      }

      // Emit trailing particle when moving fast enough
      if (velocity > 0.05 && now - lastParticleAt.current > PARTICLE_INTERVAL) {
        lastParticleAt.current = now;
        emitParticle(now);
      }

      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);

    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener("mousemove", onMove);
      window.removeEventListener("mousedown", onDown);
    };
  }, [enabled, hovering]);

  // Spawn a single fading particle at the mouse position
  const emitParticle = (now: number) => {
    const layer = particleLayerRef.current;
    if (!layer) return;
    // Cap total particles
    const existing = layer.querySelectorAll("[data-particle]");
    if (existing.length >= MAX_PARTICLES) existing[0].remove();

    const id = particleId.current++;
    const p: Particle = {
      id,
      x: mouse.current.x + (Math.random() - 0.5) * 6,
      y: mouse.current.y + (Math.random() - 0.5) * 6,
      size: 4 + Math.random() * 4,
      born: now,
    };

    const node = document.createElement("span");
    node.dataset.particle = "1";
    node.style.position = "absolute";
    node.style.left = `${p.x}px`;
    node.style.top = `${p.y}px`;
    node.style.width = `${p.size}px`;
    node.style.height = `${p.size}px`;
    node.style.borderRadius = "9999px";
    node.style.background = "rgba(199, 31, 66, 0.95)";
    node.style.boxShadow = "0 0 12px rgba(199, 31, 66, 0.65)";
    node.style.transform = "translate(-50%, -50%)";
    node.style.pointerEvents = "none";
    node.style.opacity = "0.95";
    node.style.transition = `opacity ${PARTICLE_LIFE}ms ease-out, transform ${PARTICLE_LIFE}ms ease-out, background ${PARTICLE_LIFE}ms ease-out`;
    layer.appendChild(node);
    // Drift upward and fade
    requestAnimationFrame(() => {
      node.style.transform = `translate(-50%, -50%) translateY(-22px) scale(0.2)`;
      node.style.opacity = "0";
      node.style.background = "rgba(199, 31, 66, 0.05)";
    });
    setTimeout(() => node.remove(), PARTICLE_LIFE + 50);
  };

  if (!enabled) return null;

  return (
    <div className="pointer-events-none fixed inset-0 z-[200]" aria-hidden="true">
      {/* Particle / ripple layer (raw DOM nodes appended here) */}
      <div ref={particleLayerRef} className="absolute inset-0" />

      {/* Outer soft glow */}
      <div
        ref={glowRef}
        className="absolute h-8 w-8 rounded-full opacity-0"
        style={{
          background:
            "radial-gradient(circle, rgba(199,31,66,0.55) 0%, rgba(199,31,66,0.18) 45%, transparent 75%)",
          willChange: "transform, opacity",
        }}
      />

      {/* Inner crisp dot */}
      <div
        ref={dotRef}
        className="absolute h-2 w-2 rounded-full opacity-0"
        style={{
          background: "#C71F42",
          boxShadow: "0 0 10px rgba(199,31,66,0.9), 0 0 24px rgba(199,31,66,0.45)",
          willChange: "transform, opacity",
        }}
      />
    </div>
  );
}
