"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { usePathname } from "next/navigation";
import { motion, AnimatePresence } from "framer-motion";
import { Menu, X, ChevronDown } from "lucide-react";

interface NavItem {
  label: string;
  href: string;
  dropdown?: { label: string; href: string }[];
}

const navItems: NavItem[] = [
  {
    label: "Work",
    href: "/#work",
    dropdown: [
      { label: "Aurora Goods", href: "/portfolio/aurora-goods" },
      { label: "Maison Noir", href: "/portfolio/maison-noir" },
      { label: "ECHO Motors", href: "/portfolio/echo-motors" },
      { label: "Agency Collective", href: "/portfolio/agency-collective" },
    ],
  },
  {
    label: "Services",
    href: "/#services",
    dropdown: [
      { label: "UI/UX Design", href: "/services/ui-ux" },
      { label: "Motion Graphics", href: "/services/motion-graphics" },
      { label: "Digital Marketing", href: "/services/digital-marketing" },
      { label: "Web & App Development", href: "/services/web-app-dev" },
    ],
  },
  {
    label: "Case Studies",
    href: "/#work",
    dropdown: [
      { label: "Aurora Goods", href: "/case-studies/aurora-goods" },
      { label: "Maison Noir", href: "/case-studies/maison-noir" },
      { label: "ECHO Motors", href: "/case-studies/echo-motors" },
      { label: "Agency Collective", href: "/case-studies/agency-collective" },
    ],
  },
  { label: "About", href: "/#values" },
  { label: "FAQ", href: "/#faq" },
];

export default function Navbar() {
  const pathname = usePathname();
  const [scrolled, setScrolled] = useState(false);
  const [open, setOpen] = useState(false);
  const [openDropdown, setOpenDropdown] = useState<string | null>(null);

  const isHome = pathname === "/";

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 24);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  // Close mobile menu on route change
  useEffect(() => {
    setOpen(false);
    setOpenDropdown(null);
  }, [pathname]);

  const onDark = !scrolled && !open && isHome;

  return (
    <motion.header
      initial={{ y: -40, opacity: 0 }}
      animate={{ y: 0, opacity: 1 }}
      transition={{ duration: 0.6, ease: [0.22, 1, 0.36, 1] }}
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-500 ${
        onDark
          ? "bg-transparent border-b border-transparent"
          : "bg-[#060000]/85 backdrop-blur-md border-b border-[#3a1518]"
      }`}
      onMouseLeave={() => setOpenDropdown(null)}
    >
      <nav className="mx-auto max-w-[1600px] px-5 sm:px-6 md:px-10 h-16 md:h-20 flex items-center justify-between">
        {/* Logo */}
        <Link href="/" className="flex items-center gap-2 group">
          <span className="h-2.5 w-2.5 rounded-full transition-all duration-300 group-hover:scale-150 bg-[#C71F42]" />
          <span className="font-display font-bold tracking-tight text-base sm:text-lg md:text-xl text-white">
            KATELLA <span className="font-light">DIGITAL</span>
          </span>
        </Link>

        {/* Desktop nav with dropdowns */}
        <div className="hidden md:flex items-center gap-6 lg:gap-8">
          {navItems.map((item) => (
            <div
              key={item.label}
              className="relative"
              onMouseEnter={() => setOpenDropdown(item.dropdown ? item.label : null)}
            >
              <Link
                href={item.href}
                className={`text-xs lg:text-sm font-medium tracking-wide uppercase flex items-center gap-1 transition-colors duration-300 cursor-pointer ${
                  onDark ? "text-white/90 hover:text-white" : "text-white/80 hover:text-white"
                }`}
              >
                {item.label}
                {item.dropdown && (
                  <ChevronDown
                    size={12}
                    className={`transition-transform duration-300 ${
                      openDropdown === item.label ? "rotate-180" : ""
                    }`}
                  />
                )}
              </Link>

              {/* Dropdown */}
              {item.dropdown && (
                <AnimatePresence>
                  {openDropdown === item.label && (
                    <motion.div
                      initial={{ opacity: 0, y: 10 }}
                      animate={{ opacity: 1, y: 0 }}
                      exit={{ opacity: 0, y: 10 }}
                      transition={{ duration: 0.2, ease: [0.22, 1, 0.36, 1] }}
                      className="absolute top-full left-1/2 -translate-x-1/2 mt-2 min-w-[220px] rounded-lg border shadow-xl overflow-hidden bg-[#1a0a0e] border-[#3a1518]"
                    >
                      {item.dropdown.map((d) => (
                        <Link
                          key={d.href}
                          href={d.href}
                          className="w-full text-left px-4 py-2.5 text-xs font-medium tracking-wide uppercase text-white/80 hover:bg-[#C71F42] hover:text-black transition-colors duration-200 block"
                        >
                          {d.label}
                        </Link>
                      ))}
                    </motion.div>
                  )}
                </AnimatePresence>
              )}
            </div>
          ))}
        </div>

        {/* CTA */}
        <div className="hidden md:block">
          <button
            type="button"
            onClick={() => window.dispatchEvent(new CustomEvent("open-contact-modal"))}
            className={`group inline-flex items-center gap-2 px-4 lg:px-5 py-2 lg:py-2.5 text-xs lg:text-sm font-medium tracking-wide uppercase border transition-colors duration-300 cursor-pointer ${
              onDark
                ? "bg-[#C71F42] text-black border-[#C71F42] hover:bg-transparent hover:text-[#C71F42]"
                : "bg-[#C71F42] text-black border-[#C71F42] hover:bg-transparent hover:text-[#C71F42]"
            }`}
          >
            Start a project
            <span className="transition-transform duration-300 group-hover:translate-x-1">→</span>
          </button>
        </div>

        {/* Mobile toggle */}
        <button
          onClick={() => setOpen((v) => !v)}
          className="md:hidden h-10 w-10 flex items-center justify-center transition-colors duration-300 text-white"
          aria-label="Toggle menu"
        >
          {open ? <X size={20} /> : <Menu size={20} />}
        </button>
      </nav>

      {/* Mobile menu */}
      <AnimatePresence>
        {open && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.3 }}
            className="md:hidden overflow-hidden bg-[#060000] border-t border-[#3a1518]"
          >
            <div className="px-5 sm:px-6 py-6 flex flex-col gap-4">
              {navItems.map((item) => (
                <div key={item.label}>
                  {item.dropdown ? (
                    <>
                      <p className="font-mono text-[10px] tracking-[0.25em] uppercase text-white/40 mb-2">
                        {item.label}
                      </p>
                      <div className="flex flex-col gap-2 pl-3 mb-2">
                        {item.dropdown.map((d) => (
                          <Link
                            key={d.href}
                            href={d.href}
                            className="text-left text-base font-display font-medium tracking-tight text-white/80 hover:text-white"
                          >
                            {d.label}
                          </Link>
                        ))}
                      </div>
                    </>
                  ) : (
                    <Link
                      href={item.href}
                      className="text-2xl font-display font-medium tracking-tight text-white"
                    >
                      {item.label}
                    </Link>
                  )}
                </div>
              ))}
              <button
                type="button"
                onClick={() => {
                  setOpen(false);
                  window.dispatchEvent(new CustomEvent("open-contact-modal"));
                }}
                className="mt-2 inline-flex items-center justify-center gap-2 bg-[#C71F42] text-black px-5 py-3 text-sm font-medium tracking-wide uppercase"
              >
                Start a project →
              </button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.header>
  );
}
